import json
import requests
from datetime import datetime

def parse_iso_timestamp(timestamp_str):
    try:
        return datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
    except ValueError:
        return None

def fetch_feed(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
        if not all(key in data for key in ["title", "updated", "items"]):
            return None
        return data
    except (requests.RequestException, json.JSONDecodeError):
        return None

def generate_html_report(feeds):
    html = ["<html><head><title>Feed Watch Report</title></head><body>"]

    for feed in feeds:
        name = feed["name"]
        url = feed["url"]
        data = fetch_feed(url)

        if data is None:
            html.append(f"<h2>{name}</h2><p>unavailable</p>")
            continue

        title = data["title"]
        updated = data["updated"]
        items = data["items"][:5]

        html.append(f"<h2>{name}</h2><p>{title}</p><p>{updated}</p><ul>")
        for item in items:
            html.append(f"<li><a href='{item['link']}'>{item['headline']}</a></li>")
        html.append("</ul>")

    html.append("</body></html>")
    return "\n".join(html)

def main():
    try:
        with open("feeds.json", "r") as f:
            feeds = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        print("Error: feeds.json not found or invalid.")
        return

    html_content = generate_html_report(feeds)

    with open("report.html", "w") as f:
        f.write(html_content)

if __name__ == "__main__":
    main()

