import json
import requests
from bs4 import BeautifulSoup

def process_feed(feed_name, feed_url):
    try:
        response = requests.get(feed_url)
        if response.status_code == 200:
            data = response.json()
            if isinstance(data, dict) and 'title' in data and isinstance(data['title'], str):
                title = data['title']
                items = data.get('items', [])
                if isinstance(items, list):
                    rendered_items = []
                    for item in items[:3]:
                        if isinstance(item, dict) and 'headline' in item and 'link' in item:
                            rendered_items.append(f'<li><a href="{item["link"]}">{item["headline"]}</a></li>')
                    return f'<h2>{feed_name}</h2><p>{title}</p><ul>{"".join(rendered_items)}</ul>'
                else:
                    return f'<h2>{feed_name}</h2><p>{title}</p><p>Invalid items format</p>'
            else:
                return f'<h2>{feed_name}</h2><p>Invalid title format</p>'
        else:
            return f'<h2>{feed_name}</h2><p>unavailable</p>'
    except Exception:
        return f'<h2>{feed_name}</h2><p>unavailable</p>'

def main():
    with open('feeds.json', 'r') as f:
        feeds = json.load(f)

    with open('report.html', 'w') as f:
        f.write('<html><head><title>Feed Report</title></head><body>')
        f.write('<h1>Feed Report</h1>')

        for feed in feeds:
            if isinstance(feed, dict) and 'name' in feed and 'url' in feed:
                feed_name = feed['name']
                feed_url = feed['url']
                section = process_feed(feed_name, feed_url)
                f.write(section + '\n')

        f.write('</body></html>')

if __name__ == '__main__':
    main()
